import z from 'zod';
import {type ComponentApi, DynamicStringSchema, DynamicNumberSchema} from '@a2ui/web_core/v0_9';

export const customSliderApi = {
  name: 'CustomSlider',
  schema: z.object({
    label: DynamicStringSchema.optional(),
    value: DynamicNumberSchema.optional(),
    min: DynamicNumberSchema.optional(),
    max: DynamicNumberSchema.optional(),
  }),
} satisfies ComponentApi;

/**
 * A custom component not part of any catalog, used to verify the renderer's
 * ability to handle external component types.
 */
export const customSliderComponent = createComponentImplementation(customSliderApi, ({props}) => {
  const label = props.label ?? 'Value';
  const val = typeof props.value === 'number' ? props.value : 0;
  const min = typeof props.min === 'number' ? props.min : 0;
  const max = typeof props.max === 'number' ? props.max : 100;

  const handleInput = (event: ChangeEvent<HTMLInputElement>) => {
    const newVal = Number(event.target.value);
    props.setValue?.(newVal);
  };

  return (
    <div
      className="custom-slider-container"
      style={{
        padding: '10px',
        border: '1px dashed blue',
        borderRadius: '4px',
      }}
    >
      <label>
        {label}: {val}
      </label>
      <input
        type="range"
        min={min}
        max={max}
        value={val}
        onChange={handleInput}
        style={{width: '100%'}}
      />
    </div>
  );
});

